sites_available.coretransapi.conf:
server {
    server_name api.coretransapi.com;

    # Proxy a Gunicorn (socket Unix)
    location / {
        proxy_pass http://unix:/home/markmur88/api_bank_h2/api.sock;
        include proxy_params;
    }

    listen 443 ssl; # managed by Certbot
    ssl_certificate /etc/letsencrypt/live/api.coretransapi.com/fullchain.pem; # managed by Certbot
    ssl_certificate_key /etc/letsencrypt/live/api.coretransapi.com/privkey.pem; # managed by Certbot
    include /etc/letsencrypt/options-ssl-nginx.conf; # managed by Certbot
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem; # managed by Certbot
}

server {
    if ($host = api.coretransapi.com) {
        return 301 https://$host$request_uri;
    } # managed by Certbot

    listen 80;
    server_name api.coretransapi.com;
    return 404; # managed by Certbot
}

sites_available.mi_proyecto:
server {
    listen 80 default_server;
    listen [::]:80 default_server;

    root /var/www/mi_proyecto/public;
    index index.php index.html index.htm;

    server_name _;

    location / {
        try_files $uri $uri/ /index.php?$query_string;
    }

    location ~ \.php$ {
        include snippets/fastcgi-php.conf;
        fastcgi_pass unix:/run/php/php8.2-fpm.sock;
    }

    location ~ /\.ht {
        deny all;
    }
}

sites_available.amara.coretransapi.com:
server {
    listen 80;
    server_name amara.coretransapi.com;

    # Ruta para ElizaOS
    location /elizaos {
        proxy_pass http://localhost:9182;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;
    }

    # Ruta para el simulador de banco (puerto 9181)
    location /simulador {
        proxy_pass http://localhost:9181;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;
    }

    # Página principal
    location / {
        return 200 'Servidor funcionando correctamente. Servicios disponibles: /elizaos (ElizaOS) y /simulador (Simulador de Banco)';
        add_header Content-Type text/plain;
    }
}
